<?php
namespace App\Console\Commands;use Illuminate\Console\Command;use Illuminate\Support\Facades\File;use Illuminate\Support\Facades\Storage;use Symfony\Component\Process\Process;use Throwable;
class BackupDatabase extends Command{protected $signature='backup:database';protected $description='Crea una copia de seguridad de la base de datos y elimina copias vencidas';public function handle():int{try{$disk=Storage::disk(config('backup.disk'));$driver=config('database.default');$stamp=now()->format('Y-m-d_His');$relative="backups/database_{$stamp}.sql";$temporary=storage_path("app/backup_{$stamp}.sql");if($driver==='sqlite'){$source=config('database.connections.sqlite.database');if(!$source||$source===':memory:'||!File::exists($source))throw new \RuntimeException('La base SQLite no es un archivo respaldable.');File::copy($source,$temporary);$relative="backups/database_{$stamp}.sqlite";}elseif($driver==='pgsql'){$connection=config('database.connections.pgsql');$process=new Process(['pg_dump','--no-owner','--no-privileges','--host='.$connection['host'],'--port='.$connection['port'],'--username='.$connection['username'],'--dbname='.$connection['database'],'--file='.$temporary]);$process->setEnv(['PGPASSWORD'=>(string)$connection['password']]);$process->setTimeout(600);$process->mustRun();}else throw new \RuntimeException("Controlador {$driver} no soportado.");$disk->put($relative,File::get($temporary));File::delete($temporary);$cutoff=now()->subDays(config('backup.retention_days'));foreach($disk->files('backups') as $file){if($disk->lastModified($file)<$cutoff->timestamp)$disk->delete($file);}$this->info("Copia creada: {$relative}");return self::SUCCESS;}catch(Throwable $e){if(isset($temporary))File::delete($temporary);report($e);$this->error($e->getMessage());return self::FAILURE;}}}
